kw_modvl:	jp 67
kw_andvv:	jp 72
kw_orvv:		jp 74
kw_notv:		jp 78
kw_scpltvl:	jp 80
kw_scpgtvl:	jp 84
kw_cpeqvl:	jp 96
kw_cpnevl:	jp 98
kw_strcpy:	jp 122
kw_printstrvar:	jp 129
